+      closeOtherTabsItem.setAttribute(
         "disabled",
         tabmail.tabInfo.every(info => info == currentTabInfo || !info.canClose)
       );
diff --git a/mailnews/base/prefs/content/am-server.js b/mailnews/base/prefs/content/am-server.js
index 81a5c776e8d..7b3edfa39b2 100644
